// SZ 32-bit columns expanded from Abdalla G. M. Ahmed's decomposed matrices.
// github.com/abdallagafar/nile; MIT license in third_party/nile/LICENSE.
#include "sampling.h"
void make_sz_samples(uint32_t* output, uint32_t count)
{
    for (uint32_t dimension = 0; dimension < 256; ++dimension) output[dimension] = 0;
    for (uint32_t index = 1; index < count; ++index)
    {
        uint32_t previous = index & (index-1);
        uint32_t changed = index ^ previous;
        uint32_t bit = 0;
        while ((changed >>= 1) != 0) ++bit;
        for (uint32_t dimension = 0; dimension < 256; ++dimension)
            output[index*256+dimension] = output[previous*256+dimension] ^ sz_columns[dimension*12+bit];
    }
}

